window.AUTH=window.AUTH||{};window.AUTH["23-5572"]={"d":"23-5572","id":"2023/23-5572","n":"Fischer v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Joseph Fischer","date":"2024-01-29","url":"https://www.supremecourt.gov/DocketPDF/23/23-5572/299098/20240129162026723_Fischer%20Opening%20Merits%20Brief.pdf","side":"pet","n":58},{"k":"respondent","label":"Brief of respondent United States","date":"2024-02-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-5572/301794/20240228194101353_23-5572bsUnitedStates.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Joseph Fischer","date":"2024-03-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-5572/306211/20240328162249370_Fischer%20-%20FINAL%203.28.24_A.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r55_6j36.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"by":{"0":"30"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"by":{"0":"10, 18","1":"11, 14, 21, 23, 24","2":"6, 13"},"q":[{"src":"brief","b":0,"text":"the word ‘otherwise’ can . . . refer to a crime that is similar to the listed examples in some respects but different in others.","cite":"553 U.S. 137, 144"},{"src":"brief","b":0,"text":"indicate[] that [the ‘otherwise’ clause] covers only similar crimes, rather than every crime that ‘presents a serious potential risk of physical injury to another.’","cite":"553 U.S. at 142"},{"src":"brief","b":1,"text":"particular similarity specified after the ‘otherwise.’","cite":"553 U.S. 137, 150151"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"suffcient to demonstrate that the examples do not limit the scope of the clause.","cite":"553 U. S., at 144"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"the particular similarity specifed after the `otherwise.'","cite":"553 U. S. 137, 150– 151"},{"src":"argument","who":"Mr. Green","text":"Well, I think Begay is our best case for sure."},{"src":"argument","who":"Justice Kagan","text":"I mean, what Begay does is exactly that. So you have a very good case there. And it was a complete failure. You know, Begay said we look back at this other -- at this thing that Congress did, you know, did not use in the \"otherwise\" provision and we derive various things from it and we put it in."},{"src":"argument","who":"Mr. Green","text":"We would submit that Begay was abrogated on other grounds, Your Honor, and the other grounds are the Court -- the members of the Court could not decide between an assessment of the types of things that came before \"otherwise\" versus the level of risk."}]},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"0":"13"}},{"t":"case","label":"Clark v. Suarez Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"0":"32"}},{"t":"case","label":"Davis v. Mich. Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"by":{"0":"8","1":"30","2":"4"},"q":[{"src":"brief","b":0,"text":"the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"489 U.S. 803, 809"},{"src":"brief","b":1,"text":"be read in their context and with a view to their place in the overall statutory scheme.","cite":"489 U.S. 803, 809"}]},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"13"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"10","2":"4, 5"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"by":{"0":"16"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"by":{"0":"22"}},{"t":"case","label":"Liparota v. United States","cite":"471 U.S. 419","y":1985,"id":"1984/84-5108","sc":1,"by":{"0":"30"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"by":{"0":"29, 31","1":"18, 43"},"q":[{"src":"brief","b":0,"text":"act[ed] with an intent to procure an unlawful benefit for oneself or for some other person.","cite":"138 S. Ct. 1101, 1114"},{"src":"brief","b":0,"text":"with an intent to procure an unlawful benefit either for [oneself] or for some other person.","cite":"138 S. Ct. 1101, 1114"},{"src":"brief","b":1,"text":"can refer to anything that ‘blocks,’ ‘makes difficult,’ or ‘hinders.’","cite":"138 S. Ct. 1101, 1106"},{"src":"argument","who":"General Prelogar","text":"But still, the Court has required a nexus, and that's been the requirement in cases like Marinello, Aguilar, and -- and Arthur Andersen, where the Court has said it does real narrowing work because you have to show that the natural and probable effect of the action is to obstruct."}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"The canon against surplusage is strongest when an interpretation would render superfluous another part of the same statutory scheme.","cite":"568 U.S. 371, 386"}]},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"by":{"0":"9, 10","1":"48"},"q":[{"src":"brief","b":0,"text":"it is a ‘fundamental principle of statutory construction (and, indeed, of language itself) that the meaning of a word cannot be determined in isolation, but must be drawn from the context in which it is used.’","cite":"515 U.S. 50, 56"}]},{"t":"case","label":"Star Athletica, L.L.C. v. Varsity Brands, Inc.","cite":"580 U.S. 405","y":2017,"id":"2016/15-866","sc":1,"by":{"0":"9, 10"}},{"t":"case","label":"Terminiello v. City of Chi.","cite":"337 U.S. 1","y":1949,"id":"1940-1955/337us1","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"[A] function of free speech under our system of government is to invite dispute. It may indeed best serve its high purpose when it induces a condition of unrest, creates dissatisfaction with conditions as they are, or even stirs people to anger.","cite":"337 U.S. 1, 4"}]},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"by":{"0":"19, 27, 29","1":"31, 34, 43","2":"1, 10"},"q":[{"src":"brief","b":1,"text":"more general in scope than the earlier clauses of the statute,","cite":"515 U.S. at 598"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`relationship in time, causation, or logic'","cite":"515 U. S. 593, 599"},{"src":"opinion","who":"Justice Jackson, concurring","text":"We have traditionally exercised restraint in assessing the reach of a federal criminal statute . . . out of deference to the prerogatives of Congress,","cite":"515 U. S. 593, 600"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"not a general or collective term following a list of specifc items to which a particular statu- Barrett, J., dissenting tory command is applicable.","cite":"515 U. S. 593, 615"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"relationship in time, causation, or logic","cite":"515 U. S., at 599"},{"src":"argument","who":"General Prelogar","text":"But still, the Court has required a nexus, and that's been the requirement in cases like Marinello, Aguilar, and -- and Arthur Andersen, where the Court has said it does real narrowing work because you have to show that the natural and probable effect of the action is to obstruct."}]},{"t":"case","label":"United States v. Beach","cite":"80 F.4th 1245","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/80/1245/","by":{"0":"19","2":"9"}},{"t":"case","label":"United States v. Brooks","cite":"610 F.3d 1186","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/610/1186/","by":{"0":"18"}},{"t":"case","label":"United States v. Burge","cite":"711 F.3d 803","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/711/803/","by":{"0":"19"}},{"t":"case","label":"United States v. Ermoian","cite":"752 F.3d 1165","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1165/","by":{"0":"25"}},{"t":"case","label":"United States v. Fischer","cite":"64 F.4th 329","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/64/329/","by":{"0":"1"}},{"t":"case","label":"United States v. Gordon","cite":"710 F.3d 1124","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/710/1124/","by":{"0":"20"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"by":{"0":"20, 30","1":"33, 47"},"q":[{"src":"brief","b":1,"text":"the ‘statute prohibits a substantial amount of protected speech’ relative to its ‘plainly legitimate sweep.’","cite":"599 U.S. at 770"}]},{"t":"case","label":"United States v. Kanchanalak","cite":"37 F. Supp. 2d 1","y":1999,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/37/1/","by":{"0":"22"}},{"t":"case","label":"United States v. Kelly","cite":"36 F.3d 1118","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1118/","by":{"0":"25"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"by":{"0":"31","1":"47, 48"},"q":[{"src":"brief","b":0,"text":"to conduct that neither the statute nor any prior judicial decision has fairly disclosed to be within its scope.","cite":"520 U.S. 259, 266"},{"src":"brief","b":1,"text":"due process bars courts from applying a novel construction of a criminal statute to conduct that neither the statute nor any prior judicial decision has fairly disclosed to be within its scope.","cite":"520 U.S. 259, 266"}]},{"t":"case","label":"United States v. Miller","cite":"589 F. Supp. 3d 60","y":2022,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/589/60/","by":{"0":"1, 5"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`have taken some action with respect to a document, record, or other object.'","cite":"589 F. Supp. 3d 60, 78"}]},{"t":"case","label":"United States v. Miller","cite":"605 F. Supp. 3d 63","y":2022,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/605/63/","by":{"0":"1"}},{"t":"case","label":"United States v. Nasir","cite":"17 F.4th 459","y":2021,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/17/459/","by":{"0":"30"}},{"t":"case","label":"United States v. North","cite":"910 F.2d 843","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/910/843/","by":{"0":"27, 28, 32","1":"44"},"q":[{"src":"brief","b":0,"text":"act[ing] ‘with a corrupt purpose,’ through ‘independently corrupt means,’ or both.","cite":"910 F.2d 843, 942-43"},{"src":"brief","b":0,"text":"[n]o one can seriously question that people constantly attempt, in innumerable ways, to obstruct or impede congressional committees.","cite":"910 F.2d at 882"}]},{"t":"case","label":"United States v. Perez","cite":"575 F.3d 164","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/575/164/","by":{"0":"25"}},{"t":"case","label":"United States v. Petruk","cite":"781 F.3d 438","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/781/438/","by":{"0":"19","1":"20"},"q":[{"src":"brief","b":1,"text":"operates as a catch-all to cover otherwise obstructive behavior that might not constitute a more specific offense like document destruction.","cite":"781 F.3d 438, 447"}]},{"t":"case","label":"United States v. Poindexter","cite":"951 F.2d 369","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/951/369/","by":{"0":"20, 21, 22, 25, 28","2":"17"},"q":[{"src":"brief","b":0,"text":"various forms of witness tampering, including many activities that were formerly prohibited by §§ 1503 and 1505.","cite":"951 F.2d at 382"},{"src":"brief","b":0,"text":"beyond the legitimate scope of this witness protection measure. It also is probably duplicative of [o]bstruction of justice statutes already on the books.","cite":"951 F.2d at 383"},{"src":"brief","b":2,"text":"which prohibits various forms of witness tampering, including many activities that were formerly prohibited by [Sections] 1503 and 1505.","cite":"951 F.2d 369, 382"}]},{"t":"case","label":"United States v. Reeves","cite":"752 F.2d 995","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/752/995/","by":{"0":"27, 28"}},{"t":"case","label":"United States v. Robertson","cite":"86 F.4th 355","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/86/355/","by":{"0":"26, 27","1":"44, 45","2":"20"},"q":[{"src":"brief","b":1,"text":"an understanding or awareness that what [he] [wa]s doing [wa]s wrong.","cite":"86 F.4th 355, 362"},{"src":"brief","b":1,"text":"‘[C]ongressional committees are part and parcel of a political branch of government’ that is engaged in making legislative and policy choices.","cite":"86 F.4th at 366"},{"src":"brief","b":2,"text":"us[e] of unlawful means[] or act[ing] with an unlawful purpose.","cite":"86 F.4th 355, 362"},{"src":"argument","who":"General Prelogar","text":"And just to give you a more concrete example of how this has played out in the January 6th prosecutions, I'd point to the jury instruction in the Robertson case, which we refer to and quote in part on page 44 of our brief."},{"src":"argument","who":"Justice Sotomayor","text":"You've endorsed the Robertson view. Could you tell me what you feel about the Walker view? Judge Walker being part of the majority below. I -- I assume you know that, but --"}]},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"by":{"0":"16"}},{"t":"case","label":"United States v. Stinson","cite":"592 F.3d 460","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/592/460/","by":{"0":"19"}},{"t":"case","label":"United States v. Sutherland","cite":"921 F.3d 421","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/921/421/","by":{"0":"20"}},{"t":"case","label":"United States v. Volpendesto","cite":"746 F.3d 273","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/273/","by":{"0":"19"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"[T]he commonsense canon of noscitur a sociis . . . counsels that a word is given more precise content by the neighboring words with which it is associated.","cite":"553 U.S. 285, 294"}]},{"t":"case","label":"Walters v. Metro. Educ. Enters., Inc.","cite":"519 U.S. 202","y":1997,"id":"1996/95-259","sc":1,"by":{"0":"8"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"does not, one might say, hide elephants in mouseholes.","cite":"531 U.S. 457, 468"}]},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"30"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"18","1":"26, 27, 31, 37, 38","2":"14, 15, 16"},"q":[{"src":"brief","b":0,"text":"[a] fish is no doubt an object that is tangible[,] . . . it would cut § 1519 loose from its financial-fraud mooring to hold that it encompasses any and all objects, whatever their size or significance, destroyed with obstructive intent.","cite":"574 U.S. at 532"},{"src":"brief","b":0,"text":"The Sarbanes-Oxley Act, all agree, was prompted by the exposure of Enron’s massive accounting fraud and revelations that the company’s outside auditor, Arthur Andersen LLP, had systematically destroyed potentially incriminating documents.","cite":"574 U.S. at 535"},{"src":"brief","b":1,"text":"objects used to record or preserve information.","cite":"574 U.S. at 544"},{"src":"brief","b":1,"text":"exposure of Enron’s massive accounting fraud and revelations that the company’s outside auditor, Arthur Andersen LLP, had systematically destroyed potentially incriminating documents.","cite":"574 U.S. at 535"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"impos[e] liability on a person who destroys records himself.","cite":"574 U. S., at 535"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`glosse[d] over the absence of any prescribed minimum.'","cite":"574 U. S., at 569"},{"src":"opinion","who":"Justice Jackson, concurring","text":"was prompted by the exposure of Enron's massive accounting fraud and revelations that the company's outside auditor, Arthur Andersen LLP, had systematically destroyed potentially incriminating documents.","cite":"574 U. S. 528, 535–536"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"render[ed] superfuous an entire provision passed in proximity as part of the same Act.","cite":"574 U. S. 528, 543"},{"src":"argument","who":"Mr. Green","text":"Yates is also a good case."},{"src":"argument","who":"Mr. Green","text":"Respectfully, Your Honor, a close reading of Yates, both the majority opinion and the dissenting opinion, demonstrates that this Court thought that 1519 was the backstop."},{"src":"argument","who":"Mr. Green","text":"Well, I think you can reconcile -- I mean, again, that's what the Court said about 1519 in -- in Yates. And I don't understand how it is that the government can come before you today and say we need yet another catchall, yet another omnibus crime that will sweep in all kinds of others."}]},{"t":"usc","label":"18 U.S.C. § 1503","url":"https://www.law.cornell.edu/uscode/text/18/1503","subs":["(a)"],"stext":{"head":"§1503. Influencing or injuring officer or juror generally","paras":[[0,"(a) Whoever corruptly, or by threats or force, or by any threatening letter or communication, endeavors to influence, intimidate, or impede any grand or petit juror, or officer in or of any court of the United States, or officer who may be serving at any examination or other proceeding before any United States magistrate judge or other committing magistrate, in the discharge of his duty, or injures any such grand or petit juror in his person or property on account of any verdict or indictment assented to by him, or on account of his being or having been such juror, or injures any such officer, magistrate judge, or other committing magistrate in his person or property on account of the performance of his official duties, or corruptly or by threats or force, or by any threatening letter or communication, influences, obstructs, or impedes, or endeavors to influence, obstruct, or impede, the due administration of justice, shall be punished as provided in subsection (b). If the offense under this section occurs in connection with a trial of a criminal case, and the act in violation of this section involves the threat of physical force or physical force, the maximum term of imprisonment which may be imposed for the offense shall be the higher of that otherwise provided by law or the maximum term that could have been imposed for any offense charged in such case."],[0,"(b) The punishment for an offense under this section is—"],[1,"(1) in the case of a killing, the punishment provided in sections 1111 and 1112;"],[1,"(2) in the case of an attempted killing, or a case in which the offense was committed against a petit juror and in which a class A or B felony was charged, imprisonment for not more than 20 years, a fine under this title, or both; and"],[1,"(3) in any other case, imprisonment for not more than 10 years, a fine under this title, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1503?type=usc&year=mostrecent&link-type=html"},"by":{"0":"15, 19, 20, 24","1":"3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37","2":"18, 19"},"q":[{"src":"brief","b":1,"text":"or corruptly or by threats of force, or by any threatening letter or communication, influenc[ing], obstruct[ing], or imped[ing] * * * the due administration of justice.","cite":"18 U.S.C. 1503(a)"}]},{"t":"usc","label":"18 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/18/1505","stext":{"head":"§1505. Obstruction of proceedings before departments, agencies, and committees","paras":[[0,"Whoever, with intent to avoid, evade, prevent, or obstruct compliance, in whole or in part, with any civil investigative demand duly and properly made under the Antitrust Civil Process Act, willfully withholds, misrepresents, removes from any place, conceals, covers up, destroys, mutilates, alters, or by other means falsifies any documentary material, answers to written interrogatories, or oral testimony, which is the subject of such demand; or attempts to do so or solicits another to do so; or"],[0,"Whoever corruptly, or by threats or force, or by any threatening letter or communication influences, obstructs, or impedes or endeavors to influence, obstruct, or impede the due and proper administration of the law under which any pending proceeding is being had before any department or agency of the United States, or the due and proper exercise of the power of inquiry under which any inquiry or investigation is being had by either House, or any committee of either House or any joint committee of the Congress—"],[0,"Shall be fined under this title, imprisoned not more than 5 years or, if the offense involves international or domestic terrorism (as defined in section 2331), imprisoned not more than 8 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1505?type=usc&year=mostrecent&link-type=html"},"by":{"0":"15, 20, 21","1":"3, 6, 7, 9-34, 36, 37","2":"18"}},{"t":"usc","label":"18 U.S.C. § 1507","url":"https://www.law.cornell.edu/uscode/text/18/1507","by":{"0":"24","2":"18"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(b)(2)","(c)","(c)(1)","(c)(2)","(a)(1)(A)","(a)(1)(B)","(a)(2)(A)","(a)(2)(E)","(a)(3)","(b)(1)","(d)","(d)(1)","(d)(4)"],"stext":{"head":"§1512. Tampering with a witness, victim, or an informant","paras":[[0,"(a)(1) Whoever kills or attempts to kill another person, with intent to—"],[1,"(A) prevent the attendance or testimony of any person in an official proceeding;"],[1,"(B) prevent the production of a record, document, or other object, in an official proceeding; or"],[1,"(C) prevent the communication by any person to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(2) Whoever uses physical force or the threat of physical force against any person, or attempts to do so, with intent to—"],[1,"(A) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(B) cause or induce any person to—"],[2,"(i) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(ii) alter, destroy, mutilate, or conceal an object with intent to impair the integrity or availability of the object for use in an official proceeding;"],[2,"(iii) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(iv) be absent from an official proceeding to which that person has been summoned by legal process; or"],[1,"(C) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, supervised release, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(3) The punishment for an offense under this subsection is—"],[1,"(A) in the case of a killing, the punishment provided in sections 1111 and 1112;"],[1,"(B) in the case of—"],[2,"(i) an attempt to murder; or"],[2,"(ii) the use or attempted use of physical force against any person;"],[1,"imprisonment for not more than 30 years; and"],[1,"(C) in the case of the threat of use of physical force against any person, imprisonment for not more than 20 years."],[0,"(b) Whoever knowingly uses intimidation, threatens, or corruptly persuades another person, or attempts to do so, or engages in misleading conduct toward another person, with intent to—"],[1,"(1) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(2) cause or induce any person to—"],[2,"(A) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(B) alter, destroy, mutilate, or conceal an object with intent to impair the object's integrity or availability for use in an official proceeding;"],[2,"(C) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(D) be absent from an official proceeding to which such person has been summoned by legal process; or"],[1,"(3) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(c) Whoever corruptly—"],[1,"(1) alters, destroys, mutilates, or conceals a record, document, or other object, or attempts to do so, with the intent to impair the object's integrity or availability for use in an official proceeding; or"],[1,"(2) otherwise obstructs, influences, or impedes any official proceeding, or attempts to do so,"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(d) Whoever intentionally harasses another person and thereby hinders, delays, prevents, or dissuades any person from—"],[1,"(1) attending or testifying in an official proceeding;"],[1,"(2) reporting to a law enforcement officer or judge of the United States the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[1,"(3) arresting or seeking the arrest of another person in connection with a Federal offense; or"],[1,"(4) causing a criminal prosecution, or a parole or probation revocation proceeding, to be sought or instituted, or assisting in such prosecution or proceeding;"],[0,"or attempts to do so, shall be fined under this title or imprisoned not more than 3 years, or both."],[0,"(e) In a prosecution for an offense under this section, it is an affirmative defense, as to which the defendant has the burden of proof by a preponderance of the evidence, that the conduct consisted solely of lawful conduct and that the defendant's sole intention was to encourage, induce, or cause the other person to testify truthfully."],[0,"(f) For the purposes of this section—"],[1,"(1) an official proceeding need not be pending or about to be instituted at the time of the offense; and"],[1,"(2) the testimony, or the record, document, or other object need not be admissible in evidence or free of a claim of privilege."],[0,"(g) In a prosecution for an offense under this section, no state of mind need be proved with respect to the circumstance—"],[1,"(1) that the official proceeding before a judge, court, magistrate judge, grand jury, or government agency is before a judge or court of the United States, a United States magistrate judge, a bankruptcy judge, a Federal grand jury, or a Federal Government agency; or"],[1,"(2) that the judge is a judge of the United States or that the law enforcement officer is an officer or employee of the Federal Government or a person authorized to act for or on behalf of the Federal Government or serving the Federal Government as an adviser or consultant."],[0,"(h) There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(i) A prosecution under this section or section 1503 may be brought in the district in which the official proceeding (whether or not pending or about to be instituted) was intended to be affected or in the district in which the conduct constituting the alleged offense occurred."],[0,"(j) If the offense under this section occurs in connection with a trial of a criminal case, the maximum term of imprisonment which may be imposed for the offense shall be the higher of that otherwise provided by law or the maximum term that could have been imposed for any offense charged in such case."],[0,"(k) Whoever conspires to commit any offense under this section shall be subject to the same penalties as those prescribed for the offense the commission of which was the object of the conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1512?type=usc&year=mostrecent&link-type=html"},"by":{"0":"12, 15, 21, 23, 3, 2, 9, 5, 7, 8, 9, 11, 17, 26, 28","1":"3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 3, 6, 7, 9-34, 36, 37, 35, 26, 2, 2, 2","2":"8"},"q":[{"src":"brief","b":0,"text":"Tampering with a witness, victim, or an informant.","cite":"18 U.S.C. § 1512"},{"src":"brief","b":1,"text":"alter[ ], destroy[ ], mutilate[ ], or conceal[ ] a record, document, or other object * * * with the intent to impair the object’s integrity or availability for use in an official proceeding.","cite":"18 U.S.C. 1512(c)(1)"},{"src":"brief","b":1,"text":"alter[ing], destroy[ing], mutilat[ing], or conceal[ing] a record, document, or other object, * * * with the intent to impair the object’s integrity or availability for use in an official proceeding.","cite":"18 U.S.C. 1512(c)(1)"},{"src":"brief","b":2,"text":"do not require an official proceeding.","cite":"18 U.S.C. §§ 1512(d)(4), 1519"},{"src":"argument","who":"Mr. Green","text":"So, with respect to surplusage, Your Honor, I would refer to Judge Katsas's opinion, as you did, in particular in the Joint Appendix at page 88, which lists out all of the different provisions in Section 1512."}]},{"t":"usc","label":"18 U.S.C. § 1515","url":"https://www.law.cornell.edu/uscode/text/18/1515","subs":["(b)","(a)(1)","(a)(1)(B)","(a)(1)(A)","(a)(2)(A)"],"stext":{"head":"§1515. Definitions for certain provisions; general provision","paras":[[0,"(a) As used in sections 1512 and 1513 of this title and in this section—"],[1,"(1) the term \"official proceeding\" means—"],[2,"(A) a proceeding before a judge or court of the United States, a United States magistrate judge, a bankruptcy judge, a judge of the United States Tax Court, a special trial judge of the Tax Court, a judge of the United States Court of Federal Claims, or a Federal grand jury;"],[2,"(B) a proceeding before the Congress;"],[2,"(C) a proceeding before a Federal Government agency which is authorized by law; or"],[2,"(D) a proceeding involving the business of insurance whose activities affect interstate commerce before any insurance regulatory official or agency or any agent or examiner appointed by such official or agency to examine the affairs of any person engaged in the business of insurance whose activities affect interstate commerce;"],[1,"(2) the term \"physical force\" means physical action against another, and includes confinement;"],[1,"(3) the term \"misleading conduct\" means—"],[2,"(A) knowingly making a false statement;"],[2,"(B) intentionally omitting information from a statement and thereby causing a portion of such statement to be misleading, or intentionally concealing a material fact, and thereby creating a false impression by such statement;"],[2,"(C) with intent to mislead, knowingly submitting or inviting reliance on a writing or recording that is false, forged, altered, or otherwise lacking in authenticity;"],[2,"(D) with intent to mislead, knowingly submitting or inviting reliance on a sample, specimen, map, photograph, boundary mark, or other object that is misleading in a material respect; or"],[2,"(E) knowingly using a trick, scheme, or device with intent to mislead;"],[1,"(4) the term \"law enforcement officer\" means an officer or employee of the Federal Government, or a person authorized to act for or on behalf of the Federal Government or serving the Federal Government as an adviser or consultant—"],[2,"(A) authorized under law to engage in or supervise the prevention, detection, investigation, or prosecution of an offense; or"],[2,"(B) serving as a probation or pretrial services officer under this title;"],[1,"(5) the term \"bodily injury\" means—"],[2,"(A) a cut, abrasion, bruise, burn, or disfigurement;"],[2,"(B) physical pain;"],[2,"(C) illness;"],[2,"(D) impairment of the function of a bodily member, organ, or mental faculty; or"],[2,"(E) any other injury to the body, no matter how temporary; and"],[1,"(6) the term \"corruptly persuades\" does not include conduct which would be misleading conduct but for a lack of a state of mind."],[0,"(b) As used in section 1505, the term \"corruptly\" means acting with an improper purpose, personally or by influencing another, including making a false or misleading statement, or withholding, concealing, altering, or destroying a document or other information."],[0,"(c) This chapter does not prohibit or punish the providing of lawful, bona fide, legal representation services in connection with or anticipation of an official proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1515?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 27","1":"2, 2","2":"16, 16"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"40 U.S.C. § 5104","url":"https://www.law.cornell.edu/uscode/text/40/5104","subs":["(e)(2)(G)","(e)(2)(D)"],"stext":{"head":"§5104. Unlawful activities","paras":[[0,"(a) Definitions.—In this section—"],[1,"(1) Act of physical violence.—The term \"act of physical violence\" means any act involving—"],[2,"(A) an assault or other infliction or threat of infliction of death or bodily harm on an individual; or"],[2,"(B) damage to, or destruction of, real or personal property."],[1,"(2) Dangerous weapon.—The term \"dangerous weapon\" includes—"],[2,"(A) all articles enumerated in section 14(a) of the Act of July 8, 1932 (ch. 465, 47 Stat. 654); and"],[2,"(B) a device designed to expel or hurl a projectile capable of causing injury to individuals or property, a dagger, a dirk, a stiletto, and a knife having a blade over three inches in length."],[1,"(3) Explosives.—The term \"explosives\" has the meaning given that term in section 841(d) of title 18."],[1,"(4) Firearm.—The term \"firearm\" has the meaning given that term in section 921(3) 1 of title 18."],[0,"(b) Obstruction of Roads.—A person may not occupy the roads in the United States Capitol Grounds in a manner that obstructs or hinders their proper use, or use the roads in the area of the Grounds, south of Constitution Avenue and B Street and north of Independence Avenue and B Street, to convey goods or merchandise, except to or from the United States Capitol on Federal Government service."],[0,"(c) Sale of Articles, Display of Signs, and Solicitations.—A person may not carry out any of the following activities in the Grounds:"],[1,"(1) offer or expose any article for sale."],[1,"(2) display a sign, placard, or other form of advertisement."],[1,"(3) solicit fares, alms, subscriptions, or contributions."],[0,"(d) Injuries to Property.—A person may not step or climb on, remove, or in any way injure any statue, seat, wall, fountain, or other erection or architectural feature, or any tree, shrub, plant, or turf, in the Grounds."],[0,"(e) Capitol Grounds and Buildings Security.—"],[1,"(1) Firearms, dangerous weapons, explosives, or incendiary devices.—An individual or group of individuals—"],[2,"(A) except as authorized by regulations prescribed by the Capitol Police Board—"],[3,"(i) may not carry on or have readily accessible to any individual on the Grounds or in any of the Capitol Buildings a firearm, a dangerous weapon, explosives, or an incendiary device;"],[3,"(ii) may not discharge a firearm or explosives, use a dangerous weapon, or ignite an incendiary device, on the Grounds or in any of the Capitol Buildings; or"],[3,"(iii) may not transport on the Grounds or in any of the Capitol Buildings explosives or an incendiary device; or"],[2,"(B) may not knowingly, with force and violence, enter or remain on the floor of either House of Congress."],[1,"(2) Violent entry and disorderly conduct.—An individual or group of individuals may not willfully and knowingly—"],[2,"(A) enter or remain on the floor of either House of Congress or in any cloakroom or lobby adjacent to that floor, in the Rayburn Room of the House of Representatives, or in the Marble Room of the Senate, unless authorized to do so pursuant to rules adopted, or an authorization given, by that House;"],[2,"(B) enter or remain in the gallery of either House of Congress in violation of rules governing admission to the gallery adopted by that House or pursuant to an authorization given by that House;"],[2,"(C) with the intent to disrupt the orderly conduct of official business, enter or remain in a room in any of the Capitol Buildings set aside or designated for the use of—"],[3,"(i) either House of Congress or a Member, committee, officer, or employee of Congress, or either House of Congress; or"],[3,"(ii) the Library of Congress;"],[2,"(D) utter loud, threatening, or abusive language, or engage in disorderly or disruptive conduct, at any place in the Grounds or in any of the Capitol Buildings with the intent to impede, disrupt, or disturb the orderly conduct of a session of Congress or either House of Congress, or the orderly conduct in that building of a hearing before, or any deliberations of, a committee of Congress or either House of Congress;"],[2,"(E) obstruct, or impede passage through or within, the Grounds or any of the Capitol Buildings;"],[2,"(F) engage in an act of physical violence in the Grounds or any of the Capitol Buildings; or"],[2,"(G) parade, demonstrate, or picket in any of the Capitol Buildings."],[1,"(3) Exemption of government officials.—This subsection does not prohibit any act performed in the lawful discharge of official duties by—"],[2,"(A) a Member of Congress;"],[2,"(B) an employee of a Member of Congress;"],[2,"(C) an officer or employee of Congress or a committee of Congress; or"],[2,"(D) an officer or employee of either House of Congress or a committee of that House."],[0,"(f) Parades, Assemblages, and Display of Flags.—Except as provided in section 5106 of this title, a person may not—"],[1,"(1) parade, stand, or move in processions or assemblages in the Grounds; or"],[1,"(2) display in the Grounds a flag, banner, or device designed or adapted to bring into public notice a party, organization, or movement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/40/5104?type=usc&year=mostrecent&link-type=html"},"by":{"0":"28","1":"3, 2","2":"20"}},{"t":"law","label":"Pub. L. No. 97-291","url":"https://www.govinfo.gov/link/statute/96/1248","by":{"0":"21, 22","1":"40"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"0":"13, 23","2":"19"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"1":"20, 22, 26, 27, 28","2":"15"},"q":[{"src":"brief","b":1,"text":"Had Congress intended to limit [the statute’s] reach as petitioner contends, it easily could have written","cite":"552 U.S. 214, 227"},{"src":"brief","b":1,"text":"a list of specific items separated by commas and followed by a general or collective term.","cite":"552 U.S. at 225"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"otherwise impair the integrity or availability of records, documents, objects, or other things for use in an offcial proceeding.","cite":"552 U. S., at 227"}]},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"by":{"1":"35, 43, 44, 46"},"q":[{"src":"brief","b":1,"text":"normally associated with wrongful, immoral, depraved, or evil","cite":"544 U.S. at 705"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`normally associated with wrongful, immoral, depraved, or evil' conduct,","cite":"544 U. S. 696, 705"},{"src":"argument","who":"General Prelogar","text":"And this traces to the Court's decision in Arthur Andersen, where the Court said this is a term with deep historical roots, with a settled meaning, and that it connotes not just knowledge of your actions, which is, you know, the intent to obstruct in this case, but further requires that it be done corruptly."},{"src":"argument","who":"General Prelogar","text":"But still, the Court has required a nexus, and that's been the requirement in cases like Marinello, Aguilar, and -- and Arthur Andersen, where the Court has said it does real narrowing work because you have to show that the natural and probable effect of the action is to obstruct."}]},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"by":{"1":"20"}},{"t":"case","label":"Beecham v. United States","cite":"511 U.S. 368","y":1994,"id":"1993/93-445","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"counsels in favor of interpreting the other items as possessing that attribute as well.","cite":"511 U.S. 368, 371"}]},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"by":{"1":"40","2":"4"}},{"t":"case","label":"CSX Transp., Inc. v. Alabama Dep’t of Revenue","cite":"562 U.S. 277","y":2011,"id":"2010/09-520","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"limits general terms [that] follow specific ones to matters similar to those specified.","cite":"562 U.S. 277, 294"}]},{"t":"case","label":"Chiafalo v. Washington","cite":"140 S. Ct. 2316","y":2020,"id":"2019/19-465","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"actually go toward selecting members of the Electoral College, whom each State appoints based on the popular returns.","cite":"140 S. Ct. 2316, 2319"}]},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"says in a statute what it means and means in a statute what it says there.","cite":"503 U.S. 249, 253-254"}]},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"read[ ] words or elements into a statute that do not appear on its face.","cite":"556 U.S. 568, 572"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"`[W]e ordinarily resist reading words or elements into a statute that do not appear on its face.'","cite":"556 U. S. 568, 572"}]},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"1":"37","2":"14"},"q":[{"src":"argument","who":"Mr. Green","text":"But let's -- let's also look at what the Court has said in so many different cases, in -- in Dubin, in Bond, in Yates, in Kelly. All of these cases --"}]},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"the canon against surplusage merely favors that interpretation which avoids surplusage— and petitioner[’s] interpretation no more achieves that end","cite":"566 U.S. 624, 635"}]},{"t":"case","label":"Gallardo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"must give effect to, not nullify, Congress’ choice to include limiting language in some provisions but not others.","cite":"596 U.S. 420, 431"}]},{"t":"case","label":"Gooch v. United States","cite":"297 U.S. 124","y":1936,"id":"scdb/1935-079","sc":1,"by":{"1":"19","2":"7, 11"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharms. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"by":{"1":"22","2":"12"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"by":{"1":"24"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"1":"25, 33"},"q":[{"src":"opinion","who":"Justice Barrett, dissenting","text":"is not uncommon in criminal statutes.","cite":"573 U. S. 351, 358, n. 4"}]},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"by":{"1":"19"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"1":"30"},"q":[{"src":"brief","b":1,"text":"Where Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"556 U.S. 418, 430"}]},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"by":{"1":"48"},"q":[{"src":"brief","b":1,"text":"only when a criminal statute contains a ‘grievous ambiguity or uncertainty,’ and ‘only if, after seizing everything from which aid can be derived,’ the Court ‘can make no more than a guess as to what Congress intended.’","cite":"578 U.S. 282, 295 n.8"}]},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"by":{"1":"39"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"by":{"1":"22"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"1":"34, 39"},"q":[{"src":"brief","b":1,"text":"is that it serves as a catchall for matters not specifically contemplated—known unknowns.","cite":"556 U.S. 848, 860"},{"src":"brief","b":1,"text":"serves as a catchall for matters not specifically contemplated.","cite":"556 U.S. at 860"},{"src":"opinion","who":"Justice Barrett, dissenting","text":"a catchall for matters not specifcally contemplated—known unknowns.","cite":"556 U. S. 848, 860"}]},{"t":"case","label":"S. D. Warren Co. v. Maine Bd. of Envtl. Prot.","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"by":{"1":"26"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"phrase ‘purposeful, violent, and aggressive’ ha[d] no precise textual link to the residual clause.","cite":"564 U.S. 1, 13"}]},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"by":{"1":"19, 22","2":"7, 10, 11"}},{"t":"case","label":"United States v. Ahrensfield","cite":"698 F.3d 1310","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/1310/","by":{"1":"40"},"q":[{"src":"argument","who":"General Prelogar","text":"We cite Ahrensfield. That's the case where a subject of a grand jury investigation was tipped off about the existence of the investigation, but there was no, you know, kind of material impact or -- or clear evidence of -- of impairment of the evidence or availability of testimony or physical documents."}]},{"t":"case","label":"United States v. Alford","cite":"89 F.4th 943","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/89/943/","by":{"1":"5"},"q":[{"src":"brief","b":1,"text":"cleared and checked for threats like lurkers or explosives.","cite":"89 F.4th 943, 953"}]},{"t":"case","label":"United States v. Banks","cite":"942 F.2d 1576","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/942/1576/","by":{"1":"31"}},{"t":"case","label":"United States v. Cohn","cite":"452 F.2d 881","y":1971,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/452/881/","by":{"1":"31"}},{"t":"case","label":"United States v. Fitzsimons","cite":"605 F. Supp. 3d 132","y":2022,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/605/132/","by":{"1":"29"}},{"t":"case","label":"United States v. Frank","cite":"354 F.3d 910","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/354/910/","by":{"1":"33"}},{"t":"case","label":"United States v. Friske","cite":"640 F.3d 1288","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/640/1288/","by":{"1":"43"}},{"t":"case","label":"United States v. Gray","cite":"652 F. Supp. 3d 112","y":2023,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/652/112/","by":{"1":"30"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"by":{"1":"48"}},{"t":"case","label":"United States v. Howard","cite":"569 F.2d 1331","y":1978,"url":"https://www.courtlistener.com/c/F.2d/569/1331/","by":{"1":"31, 33","2":"18"},"q":[{"src":"opinion","who":"Justice Barrett, dissenting","text":"acts similar in manner to those prescribed by the statute's specifc language.","cite":"569 F. 2d 1331, 1333, 1335"}]},{"t":"case","label":"United States v. Lester","cite":"749 F.2d 1288","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/749/1288/","by":{"1":"31"}},{"t":"case","label":"United States v. Reich","cite":"479 F.3d 179","y":2007,"url":"https://www.courtlistener.com/c/F.3d/479/179/","by":{"1":"40"},"q":[{"src":"argument","who":"Justice Alito","text":"What about the Second Circuit's decision in U.S. versus Reich, where what was involved was not evidence, it was a forged court order. Would that fall within (c)(2)?"},{"src":"argument","who":"General Prelogar","text":"Justice Alito mentioned the Reich case as well, and that's another one where it was a forged court order that prompted the litigant to dismiss a mandamus petition."},{"src":"argument","who":"Justice Sotomayor","text":"I know the Reich case because I decided it. However, the tip cases, are they in your briefs?"}]},{"t":"case","label":"United States v. Schaffner","cite":"715 F.2d 1099","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/715/1099/","by":{"1":"31"}},{"t":"case","label":"United States v. Sussman","cite":"709 F.3d 155","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/709/155/","by":{"1":"32","2":"18"}},{"t":"case","label":"United States v. Young","cite":"916 F.3d 368","y":2019,"url":"https://www.courtlistener.com/c/F.3d/916/368/","by":{"1":"43","2":"21"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"words generally should be ‘interpreted as taking their ordinary, contemporary, common meaning . . . at the time Congress enacted the statute.’","cite":"585 U.S. 274, 284"}]},{"t":"const","label":"Amendment XII, Section 2","text":"The Electors shall meet in their respective states and vote by ballot for President and Vice-President, one of whom, at least, shall not be an inhabitant of the same state with themselves; they shall name in their ballots the person voted for as President, and in distinct ballots the person voted for as Vice-President, and they shall make distinct lists of all persons voted for as President, and of all persons voted for as Vice-President, and of the number of votes for each, which lists they shall sign and certify, and transmit sealed to the seat of the government of the United States, directed to the President of the Senate; -- the President of the Senate shall, in the presence of the Senate and House of Representatives, open all the certificates and the votes shall then be counted; -- The person having the greatest number of votes for President, shall be the President, if such number be a majority of the whole number of Electors appointed; and if no person have such majority, then from the persons having the highest numbers not exceeding three on the list of those voted for as President, the House of Representatives shall choose immediately, by ballot, the President. But in choosing the President, the votes shall be taken by states, the representation from each state having one vote; a quorum for this purpose shall consist of a member or members from two-thirds of the states, and a majority of all the states shall be necessary to a choice. [And if the House of Representatives shall not choose a President whenever the right of choice shall devolve upon them, before the fourth day of March next following, then the Vice-President shall act as President, as in the case of the death or other constitutional disability of the President. --] The person having the greatest number of votes as Vice-President, shall be the Vice-President, if such number be a majority of the whole number of Electors appointed, and if no person have a majority, then from the two highest numbers on the list, the Senate shall choose the Vice-President; a quorum for the purpose shall consist of two-thirds of the whole number of Senators, and a majority of the whole number shall be necessary to a choice. But no person constitutionally ineligible to the office of President shall be eligible to that of Vice-President of the United States.","by":{"1":"32"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)(2)(B)","(e)(2)(B)(ii)(2000)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 23"},"q":[{"src":"opinion","who":"Justice Barrett, dissenting","text":"is burglary, arson, or extortion, involves use of explosives, or otherwise involves conduct that presents a serious potential risk of physical injury.","cite":"18 U. S. C. § 924(e)(2)(B)(ii)"}]},{"t":"usc","label":"3 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/3/1","by":{"1":"3"}},{"t":"usc","label":"3 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/3/15","subs":["(2018)"],"by":{"1":"37, 39"},"q":[{"src":"brief","b":1,"text":"in the Hall of the House of Representatives at the hour of 1 o’clock in the afternoon.","cite":"3 U.S.C. 15"},{"src":"argument","who":"Mr. Green","text":"And I would submit, Your Honor, too that as the briefing indicates, ejusdem generis and -- and noscitur a sociis, those two venerated Latin canons, also operate in our favor here, as well as the broader context of Chapter 73 and -- and -- and Section 15."},{"src":"argument","who":"Mr. Green","text":"We didn't get what we wanted in Section 15, so now we'll go to 1512(c)(2) and see if we can expand that in this way to cover something that it has never covered before."}]},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2, 3, 7, 34"}},{"t":"usc","label":"18 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/18/111","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/18/231","subs":["(a)(3)"],"by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 514","url":"https://www.law.cornell.edu/uscode/text/18/514","subs":["(a)(1)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 757","url":"https://www.law.cornell.edu/uscode/text/18/757","by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/18/1519","by":{"1":"2"},"q":[{"src":"opinion","who":"Justice Barrett, dissenting","text":"cover[ing] up, falsif[ying], or mak[ing] a false entry in","cite":"18 U. S. C. § 1519"}]},{"t":"usc","label":"18 U.S.C. § 1752","url":"https://www.law.cornell.edu/uscode/text/18/1752","subs":["(a)(1)","(a)(2)"],"by":{"1":"2, 2"}},{"t":"usc","label":"18 U.S.C. § 2232","url":"https://www.law.cornell.edu/uscode/text/18/2232","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(6)"],"by":{"1":"36"}},{"t":"usc","label":"26 U.S.C. § 7212","url":"https://www.law.cornell.edu/uscode/text/26/7212","subs":["(a)"],"by":{"1":"43, 46"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"by":{"2":"14"},"q":[{"src":"opinion","who":"Justice Barrett, dissenting","text":"embrace only objects similar in nature to those objects enumerated by the preceding specifc words.","cite":"532 U. S. 105, 115"},{"src":"argument","who":"Justice Alito","text":"What about the Second Circuit's decision in U.S. versus Reich, where what was involved was not evidence, it was a forged court order. Would that fall within (c)(2)?"},{"src":"argument","who":"Mr. Green","text":"The \"corruptly,\" which has been construed to be the mens rea up there, is not different than -- at least on this reading, is not -- is not -- or on the accepted reading by the D.C. Circuit right now is not different than -- than some form of specific intent."},{"src":"argument","who":"General Prelogar","text":"You know, Justice Alito touched on them, and they're reflected in the competing interpretations between Judge Katsas on the D.C. Circuit and Judge Nichols on the district court."}]},{"t":"case","label":"Hermann v. Cencom Cable Assocs., Inc.","cite":"978 F.2d 978","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/978/978/","by":{"2":"4"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. ___","y":2024,"court":"U.S. Mar. 15","id":"2023/22-340","sc":1,"by":{"2":"3, 6"}},{"t":"case","label":"Swift v. California","cite":"384 F.3d 1184","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/384/1184/","by":{"2":"17"}},{"t":"case","label":"United States v. Guardiola Ramirez","cite":"2006 WL 573917","y":2006,"court":"D.P.R. Mar. 8","by":{"2":"10"}},{"t":"case","label":"United States v. Hutcherson","cite":"2006 WL 270019","y":2006,"court":"W.D. Va. Feb. 3","by":{"2":"9"}},{"t":"case","label":"United States v. Lucas","cite":"499 F.3d 769","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/499/769/","by":{"2":"9"}},{"t":"case","label":"United States v. Mintmire","cite":"507 F.3d 1273","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/507/1273/","by":{"2":"9"}},{"t":"case","label":"Unied States v. Ramos","cite":"537 F.3d 439","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/537/439/","by":{"2":"21"}},{"t":"case","label":"Villarreal v. R.J. Reynolds Tobacco Co.","cite":"839 F.3d 958","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/958/","by":{"2":"5, 7, 10"}},{"t":"case","label":"Wheaton v. McCarthy","cite":"800 F.3d 282","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/800/282/","by":{"2":"4"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","by":{"2":"19"}},{"t":"usc","label":"18 U.S.C. § 1504","url":"https://www.law.cornell.edu/uscode/text/18/1504","by":{"2":"18"}},{"t":"usc","label":"18 U.S.C. § 1509","url":"https://www.law.cornell.edu/uscode/text/18/1509","by":{"2":"19"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(c)"],"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"any officer of customs or excise or any other law enforcement officer.","cite":"28 U.S.C. § 2680(c)"}]}]};